import { useEffect, useMemo, useRef, useState } from 'react';
import { Activity as ActivityIcon, AlertTriangle, Archive, Bell, Blocks, CalendarDays, Check, ChevronDown, CircleUserRound, ClipboardCheck, Columns3, FileText, FolderKanban, Gauge, LayoutDashboard, ListChecks, LogOut, Menu, Moon, MoreHorizontal, Plus, ShieldCheck, Sun, Users, X } from 'lucide-react';
import { isConfigured } from './supabase';
import { useAuth } from './auth';
import { loadWorkspace, createTask, updateTask, archiveTask, addChecklistItem, setChecklistItem, deleteChecklistItem, addComment, createProject, updateProject, createContent, updateContent, addProfile, addPlatform, createMeeting, convertActionToTask, createNote, downloadBackup } from './db';
import type { ContentItem, Profile, Project, Status, Task, Workspace } from './types';

const labels: Record<string, string> = { in_progress: 'In progress', at_risk: 'At risk', on_track: 'On track', on_hold: 'On hold', due_today: 'Due today', due_tomorrow: 'Due tomorrow', follow_up: 'Follow up', in_review: 'In review', changes_requested: 'Changes requested' };
const nice = (v: string) => labels[v] || v.replaceAll('_', ' ').replace(/\b\w/g, c => c.toUpperCase());
const shortDate = (v?: string | null) => v ? new Intl.DateTimeFormat('en-IN', { day: 'numeric', month: 'short' }).format(new Date(`${v}T12:00:00`)) : 'No date';
const dateTime = (v: string) => new Intl.DateTimeFormat('en-IN', { day: 'numeric', month: 'short', hour: 'numeric', minute: '2-digit' }).format(new Date(v));
const person = (ws: Workspace, id?: string | null) => ws.profiles.find(p => p.id === id);
const project = (ws: Workspace, id?: string | null) => ws.projects.find(p => p.id === id);
const platform = (ws: Workspace, id?: string | null) => ws.platforms.find(p => p.id === id);
const isTyping = () => ['INPUT', 'TEXTAREA', 'SELECT'].includes(document.activeElement?.tagName || '');

const navGroups = [
  ['WORKSPACE', [['dashboard', 'Dashboard', LayoutDashboard], ['my-work', 'My Work', ListChecks], ['tasks', 'All Tasks', Columns3], ['projects', 'Projects', FolderKanban], ['calendar', 'Calendar', CalendarDays]]],
  ['CONTENT', [['content-calendar', 'Content Calendar', CalendarDays], ['content-pipeline', 'Content Pipeline', Columns3]]],
  ['TEAM', [['team', 'Team', Users], ['workload', 'Workload', Gauge]]],
  ['MANAGEMENT', [['attention', 'Needs Attention', AlertTriangle], ['weekly', 'Weekly Review', ClipboardCheck], ['activity', 'Activity', ActivityIcon]]],
  ['OTHER', [['notes', 'Notes', FileText], ['settings', 'Settings', Users]]],
] as const;

export default function App() {
  const auth = useAuth();
  if (!isConfigured) return <ConfigMissing />;
  if (auth.loading) return <Loading />;
  if (!auth.session) return <LoginScreen auth={auth} />;
  if (auth.noAccess) return <NoAccess signOut={auth.signOut} />;
  if (!auth.profile) return <ErrorState message={auth.error} retry={auth.refresh} />;
  return <Workspace_ active={auth.profile} signOut={auth.signOut} />;
}

function ConfigMissing() {
  return <div className="center-state"><ShieldCheck /><h2>Supabase is not configured</h2><p>Add VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY to a .env file, then restart.</p></div>;
}
function Loading() { return <div className="center-state"><div className="pulse-logo">SS</div><p>Opening your workspace…</p></div>; }
function ErrorState({ message, retry }: { message: string; retry: () => void }) {
  return <div className="center-state"><AlertTriangle /><h2>Workspace couldn't open</h2><p>{message || 'Please try again.'}</p><button className="primary" onClick={retry}>Try again</button></div>;
}
function NoAccess({ signOut }: { signOut: () => void }) {
  return <div className="center-state"><ShieldCheck /><h2>This account has no workspace access</h2><p>Ask a COO OS admin to add your email under Settings → Team before you sign up.</p><button className="secondary" onClick={signOut}>Sign out</button></div>;
}

function LoginScreen({ auth }: { auth: ReturnType<typeof useAuth> }) {
  const [mode, setMode] = useState<'signin' | 'signup'>('signin');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [done, setDone] = useState(false);
  const submit = async (e: React.FormEvent) => {
    e.preventDefault(); setError(''); setBusy(true);
    try {
      if (mode === 'signin') await auth.signIn(email, password);
      else { await auth.signUp(email, password); setDone(true); }
    } catch (err) { setError((err as Error).message); } finally { setBusy(false); }
  };
  return <div className="profile-gate"><div className="gate-panel login-panel">
    <div className="gate-brand"><div className="brand-mark">SS</div><span>SHADOW SECURITY · COO OS</span></div>
    <h1>{mode === 'signin' ? 'Sign in' : 'Create your account'}</h1>
    <p>{mode === 'signin' ? 'Use the email and password your admin set up for you.' : 'Only pre-added team emails can create an account. If yours was not added yet, ask your admin first.'}</p>
    {done ? <div className="notice"><ShieldCheck size={17} /><span>Check your email to confirm your account, then sign in.</span></div> : <form className="login-form" onSubmit={submit}>
      <Field label="Work email"><input type="email" required autoFocus value={email} onChange={e => setEmail(e.target.value)} /></Field>
      <Field label="Password"><input type="password" required minLength={6} value={password} onChange={e => setPassword(e.target.value)} /></Field>
      {error ? <div className="blocker"><AlertTriangle size={16} /><span>{error}</span></div> : null}
      <button className="primary" type="submit" disabled={busy}>{busy ? 'Please wait…' : mode === 'signin' ? 'Sign in' : 'Create account'}</button>
    </form>}
    <button className="link-button" onClick={() => { setMode(mode === 'signin' ? 'signup' : 'signin'); setError(''); setDone(false); }}>
      {mode === 'signin' ? "New here? Create an account" : 'Already have an account? Sign in'}
    </button>
    <div className="gate-note"><ShieldCheck size={16} /> Your admin controls who can access this workspace.</div>
  </div></div>;
}

function Workspace_({ active, signOut }: { active: Profile; signOut: () => void }) {
  const [theme, setTheme] = useState(localStorage.getItem('coo-theme') || 'light');
  const [ws, setWs] = useState<Workspace | null>(null);
  const [page, setPage] = useState(active.access_role === 'admin' ? 'dashboard' : 'my-work');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [selectedTask, setSelectedTask] = useState<string | null>(null);
  const [quick, setQuick] = useState<string | null>(null);
  const [searchOpen, setSearchOpen] = useState(false);
  const [notificationsOpen, setNotificationsOpen] = useState(false);
  const [mobileNav, setMobileNav] = useState(false);
  const [toast, setToast] = useState('');
  const load = async () => { try { setError(''); setWs(await loadWorkspace()); } catch (e) { setError((e as Error).message); } finally { setLoading(false); } };
  useEffect(() => { document.documentElement.dataset.theme = theme; localStorage.setItem('coo-theme', theme); }, [theme]);
  useEffect(() => { load(); }, []);
  useEffect(() => { const key = (e: KeyboardEvent) => { if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') { e.preventDefault(); setSearchOpen(true); } if (e.key.toLowerCase() === 'n' && !e.ctrlKey && !e.metaKey && !isTyping()) { e.preventDefault(); setQuick('task'); } if (e.key === 'Escape') { setSearchOpen(false); setQuick(null); setSelectedTask(null); } }; addEventListener('keydown', key); return () => removeEventListener('keydown', key); }, []);
  const mutate = async (fn: () => Promise<unknown>, message = 'Saved') => { try { await fn(); await load(); setToast(message); setTimeout(() => setToast(''), 2600); return true; } catch (e) { setToast((e as Error).message); setTimeout(() => setToast(''), 3500); return false; } };
  if (loading) return <Loading />;
  if (error || !ws) return <ErrorState message={error} retry={() => { setLoading(true); load(); }} />;
  const coo = active.access_role === 'admin';
  const go = (next: string) => { setPage(next); setMobileNav(false); };
  return <div className="app-shell">
    <aside className={`sidebar ${mobileNav ? 'open' : ''}`}>
      <div className="brand"><div className="brand-mark">SS</div><div><strong>Shadow Security</strong><span>COO OS</span></div><button className="icon mobile-only" onClick={() => setMobileNav(false)} aria-label="Close menu"><X size={18} /></button></div>
      <nav>{navGroups.map(([group, items]) => {
        if (!coo && (group === 'MANAGEMENT' || group === 'TEAM')) return null;
        const visible = items.filter(([id]) => coo || id !== 'dashboard');
        return <section key={group}><div className="nav-label">{group}</div>{visible.map(([id, label, Icon]) => <button key={id} className={page === id ? 'active' : ''} onClick={() => go(id)}><Icon size={16} /><span>{label}</span>{id === 'attention' && ws.attention.overdue.length > 0 ? <b className="nav-count">{ws.attention.overdue.length}</b> : null}</button>)}</section>;
      })}</nav>
      <div className="sidebar-foot"><button onClick={() => setQuick('task')}><Plus size={16} /> New task <kbd>N</kbd></button></div>
    </aside>
    <main className="main-shell">
      <header className="topbar"><button className="icon mobile-only" onClick={() => setMobileNav(true)} aria-label="Open menu"><Menu size={19} /></button><div className="workspace-title">{nice(page)}</div><button className="search-trigger" onClick={() => setSearchOpen(true)}><CircleUserRound size={16} /><span>Search workspace</span><kbd>Ctrl K</kbd></button><div className="top-actions"><button className="quick-button" onClick={() => setQuick('task')}><Plus size={16} /><span>Quick add</span></button><button className="icon" onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')} aria-label="Change theme">{theme === 'light' ? <Moon size={17} /> : <Sun size={17} />}</button><div className="popover-wrap"><button className="icon has-dot" onClick={() => setNotificationsOpen(!notificationsOpen)} aria-label="Notifications"><Bell size={17} /></button>{notificationsOpen ? <Notifications ws={ws} /> : null}</div><ProfileMenu active={active} signOut={signOut} /></div></header>
      <div className="page"><PageRouter page={page} ws={ws} active={active} coo={coo} go={go} setTask={setSelectedTask} setQuick={setQuick} mutate={mutate} /></div>
    </main>
    {selectedTask ? <TaskDrawer ws={ws} taskId={selectedTask} close={() => setSelectedTask(null)} mutate={mutate} actorId={active.id} /> : null}
    {quick ? <QuickAdd type={quick} ws={ws} actor={active} close={() => setQuick(null)} mutate={mutate} /> : null}
    {searchOpen ? <SearchPalette ws={ws} close={() => setSearchOpen(false)} go={go} setTask={setSelectedTask} /> : null}
    {toast ? <div className="toast">{toast}</div> : null}
    {mobileNav ? <div className="scrim" onClick={() => setMobileNav(false)} /> : null}
  </div>;
}

function ProfileMenu({ active, signOut }: { active: Profile; signOut: () => void }) {
  const [open, setOpen] = useState(false);
  return <div className="popover-wrap"><button className="profile-button" onClick={() => setOpen(!open)}><span className="avatar small">{active.name.slice(0, 2).toUpperCase()}</span><span>{active.name}</span><ChevronDown size={14} /></button>{open ? <div className="popover profile-pop"><div className="popover-title">{active.role} · {active.access_role === 'admin' ? 'Admin' : 'Member'}</div><button onClick={signOut}><LogOut size={15} /><span><strong>Sign out</strong></span></button></div> : null}</div>;
}
function Notifications({ ws }: { ws: Workspace }) { return <div className="popover notifications"><div className="popover-title">Notifications</div>{ws.notifications.length ? ws.notifications.map(n => <div className="notification" key={n.id}><span className="notification-dot" /><div>{n.message}<small>{dateTime(n.created_at)}</small></div></div>) : <Empty compact title="You're caught up" />}</div>; }

function PageRouter(props: { page: string; ws: Workspace; active: Profile; coo: boolean; go: (x: string) => void; setTask: (x: string) => void; setQuick: (x: string) => void; mutate: any }) {
  const { page } = props;
  if (page === 'dashboard') return <Dashboard {...props} />;
  if (page === 'my-work') return <MyWork {...props} />;
  if (page === 'tasks') return <TasksPage {...props} />;
  if (page === 'projects') return <ProjectsPage {...props} />;
  if (page === 'calendar') return <CalendarPage {...props} />;
  if (page === 'content-calendar') return <CalendarPage {...props} contentOnly />;
  if (page === 'content-pipeline') return <ContentPipeline {...props} />;
  if (page === 'team') return <TeamPage {...props} />;
  if (page === 'workload') return <WorkloadPage {...props} />;
  if (page === 'attention') return <AttentionPage {...props} />;
  if (page === 'weekly') return <WeeklyPage {...props} />;
  if (page === 'activity') return <ActivityPage {...props} />;
  if (page === 'notes') return <NotesPage {...props} />;
  return <SettingsPage {...props} />;
}

function Header({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: React.ReactNode }) { return <div className="page-header"><div>{eyebrow ? <div className="eyebrow">{eyebrow}</div> : null}<h1>{title}</h1>{description ? <p>{description}</p> : null}</div>{action}</div>; }

function Dashboard({ ws, active, go, setQuick, setTask }: { ws: Workspace; active: Profile; go: (x: string) => void; setQuick: (x: string) => void; setTask: (x: string) => void }) {
  const metrics = [['overdue', 'Overdue'], ['due_today', 'Due today'], ['blocked', 'Blocked'], ['review', 'Awaiting review'], ['follow_up', 'Follow up'], ['at_risk', 'Projects at risk']];
  const today = ws.tasks.filter(t => t.due_date === ws.today && t.status !== 'done').slice(0, 8);
  return <><Header eyebrow={new Intl.DateTimeFormat('en-IN', { weekday: 'long', day: 'numeric', month: 'long' }).format(new Date())} title={`Good ${new Date().getHours() < 12 ? 'morning' : new Date().getHours() < 17 ? 'afternoon' : 'evening'}, ${active.name}`} description="Here is what needs attention across Shadow Security." action={<button className="primary" onClick={() => setQuick('task')}><Plus size={16} /> New task</button>} /><section><div className="section-title"><h2>Needs attention</h2><button onClick={() => go('attention')}>View all</button></div><div className="metric-strip">{metrics.map(([key, label]) => <button key={key} onClick={() => go('attention')} className={key === 'overdue' || key === 'blocked' ? 'danger' : ''}><strong>{(ws.attention as any)[key].length}</strong><span>{label}</span></button>)}</div></section><div className="dashboard-grid"><section className="span-2"><div className="section-title"><h2>Today's work</h2><button onClick={() => go('tasks')}>All tasks</button></div><TaskTable tasks={today} ws={ws} setTask={setTask} /></section><section><div className="section-title"><h2>Team pulse</h2><button onClick={() => go('workload')}>Workload</button></div><div className="pulse-list">{ws.workload.filter(w => w.active > 0).sort((a, b) => b.active - a.active).slice(0, 7).map(w => <button key={w.profile_id} onClick={() => go('team')}><span className="avatar small">{person(ws, w.profile_id)?.name.slice(0, 2)}</span><span><strong>{person(ws, w.profile_id)?.name}</strong><small>{w.active} active · {w.blocked ? `${w.blocked} blocked` : `${w.due_week} due this week`}</small></span><Status value={w.level} /></button>)}</div></section><section className="span-2"><div className="section-title"><h2>Project pulse</h2><button onClick={() => go('projects')}>All projects</button></div><div className="project-pulse">{ws.projects.slice(0, 5).map(p => <div key={p.id}><div><strong>{p.name}</strong><small>{p.completed}/{p.taskCount} tasks · {shortDate(p.deadline)}</small></div><div className="progress"><i style={{ width: `${p.progress}%` }} /></div><b>{p.progress}%</b><Status value={p.health} /></div>)}</div></section><section><div className="section-title"><h2>Content pulse</h2><button onClick={() => go('content-pipeline')}>Pipeline</button></div><div className="stat-list"><div><span>Due today</span><b>{ws.content.filter(c => c.publish_date === ws.today).length}</b></div><div><span>In review</span><b>{ws.content.filter(c => c.stage === 'review').length}</b></div><div><span>Scheduled</span><b>{ws.content.filter(c => c.stage === 'scheduled').length}</b></div><div><span>Published</span><b>{ws.content.filter(c => c.stage === 'published').length}</b></div></div></section></div></>;
}
function MyWork({ ws, active, setTask }: { ws: Workspace; active: Profile; setTask: (x: string) => void }) {
  const mine = ws.tasks.filter(t => t.assignee_id === active.id && t.status !== 'done');
  const groups = [['Overdue', mine.filter(t => t.due_date && t.due_date < ws.today)], ['Today', mine.filter(t => t.due_date === ws.today)], ['Upcoming', mine.filter(t => !t.due_date || t.due_date > ws.today)], ['Follow-ups', mine.filter(t => t.follow_up_date && t.follow_up_date <= ws.today)]];
  return <><Header eyebrow="PERSONAL WORKSPACE" title={`${active.name}'s work`} description="Your assignments, deadlines, content, and follow-ups in one place." /><div className="my-work-grid">{groups.map(([title, tasks]: any) => <section key={title}><div className="section-title"><h2>{title}</h2><span>{tasks.length}</span></div><TaskTable tasks={tasks.slice(0, 8)} ws={ws} setTask={setTask} /></section>)}<section><div className="section-title"><h2>My projects</h2></div><div className="simple-list">{ws.projects.filter(p => p.owner_id === active.id || p.team.includes(active.id)).map(p => <div key={p.id}><strong>{p.name}</strong><span>{p.progress}% · {nice(p.health)}</span></div>)}</div></section><section><div className="section-title"><h2>My content</h2></div><div className="simple-list">{ws.content.filter(c => [c.owner_id, c.writer_id, c.designer_id, c.reviewer_id].includes(active.id)).slice(0, 8).map(c => <div key={c.id}><strong>{c.title}</strong><span>{nice(c.stage)} · {shortDate(c.publish_date)}</span></div>)}</div></section></div></>;
}
function TasksPage({ ws, setTask, setQuick, mutate, active }: { ws: Workspace; setTask: (x: string) => void; setQuick: (x: string) => void; mutate: any; active: Profile }) {
  const [view, setView] = useState<'board' | 'list'>('board');
  const [assignee, setAssignee] = useState(''); const [projectFilter, setProjectFilter] = useState('');
  const filtered = ws.tasks.filter(t => (!assignee || t.assignee_id === assignee) && (!projectFilter || t.project_id === projectFilter));
  const statuses: Status[] = ['backlog', 'todo', 'in_progress', 'review', 'blocked', 'done'];
  const drop = (e: React.DragEvent, status: Status) => { e.preventDefault(); const id = e.dataTransfer.getData('task'); const t = ws.tasks.find(x => x.id === id); if (id) mutate(() => updateTask(id, { status }, active.id, t), `Moved to ${nice(status)}`); };
  return <><Header eyebrow="WORKSPACE" title="All tasks" description="Plan, assign, move, and finish work without losing context." action={<button className="primary" onClick={() => setQuick('task')}><Plus size={16} /> New task</button>} /><div className="toolbar"><div className="segmented"><button className={view === 'board' ? 'active' : ''} onClick={() => setView('board')}><Columns3 size={15} /> Board</button><button className={view === 'list' ? 'active' : ''} onClick={() => setView('list')}><ListChecks size={15} /> List</button></div><select value={assignee} onChange={e => setAssignee(e.target.value)}><option value="">All assignees</option>{ws.profiles.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select><select value={projectFilter} onChange={e => setProjectFilter(e.target.value)}><option value="">All projects</option>{ws.projects.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></div>{view === 'board' ? <div className="kanban">{statuses.map(status => <div className="kanban-column" key={status} onDragOver={e => e.preventDefault()} onDrop={e => drop(e, status)}><div className="column-head"><span><i className={`dot ${status}`} />{nice(status)}</span><b>{filtered.filter(t => t.status === status).length}</b></div><div className="column-body">{filtered.filter(t => t.status === status).map(t => <TaskCard key={t.id} task={t} ws={ws} open={() => setTask(t.id)} />)}</div></div>)}</div> : <TaskTable tasks={filtered} ws={ws} setTask={setTask} />}</>;
}
function TaskCard({ task, ws, open }: { task: Task; ws: Workspace; open: () => void }) { const checks = ws.checklist.filter(c => c.task_id === task.id); return <button draggable onDragStart={e => { e.dataTransfer.setData('task', task.id); e.dataTransfer.effectAllowed = 'move'; }} onClick={open} className="task-card"><div className="card-top"><Priority value={task.priority} /><MoreHorizontal size={15} /></div><strong>{task.title}</strong><span className="task-project">{project(ws, task.project_id)?.name || 'No project'}</span>{checks.length ? <div className="check-progress"><Check size={13} />{checks.filter(c => c.completed).length}/{checks.length}</div> : null}<div className="task-meta"><span className="avatar tiny">{person(ws, task.assignee_id)?.name.slice(0, 2) || '—'}</span><time className={task.due_date && task.due_date < ws.today && task.status !== 'done' ? 'overdue' : ''}>{shortDate(task.due_date)}</time></div></button>; }
function TaskTable({ tasks, ws, setTask }: { tasks: Task[]; ws: Workspace; setTask: (x: string) => void }) { if (!tasks.length) return <Empty compact title="Nothing here" text="No work matches this view." />; return <div className="task-table">{tasks.map(t => <button key={t.id} onClick={() => setTask(t.id)}><span className={`status-box ${t.status}`}><Check size={12} /></span><span className="task-title"><strong>{t.title}</strong><small>{project(ws, t.project_id)?.name || 'No project'}</small></span><span>{person(ws, t.assignee_id)?.name || 'Unassigned'}</span><Priority value={t.priority} /><time className={t.due_date && t.due_date < ws.today && t.status !== 'done' ? 'overdue' : ''}>{shortDate(t.due_date)}</time><Status value={t.status} /></button>)}</div>; }
function ProjectsPage({ ws, setQuick }: { ws: Workspace; setQuick: (x: string) => void }) { return <><Header eyebrow="PORTFOLIO" title="Projects" description="Delivery, ownership, deadlines, and risk—without vanity analytics." action={<button className="primary" onClick={() => setQuick('project')}><Plus size={16} /> New project</button>} /><div className="data-table projects-table"><div className="table-head"><span>Project</span><span>Owner</span><span>Progress</span><span>Deadline</span><span>Health</span></div>{ws.projects.map(p => <div className="table-row" key={p.id}><span><strong>{p.name}</strong><small>{p.description}</small></span><span>{person(ws, p.owner_id)?.name}</span><span><div className="progress"><i style={{ width: `${p.progress}%` }} /></div><small>{p.progress}% · {p.completed}/{p.taskCount} tasks</small></span><span>{shortDate(p.deadline)}</span><span><Status value={p.health} />{p.reasons.length ? <small>{p.reasons[0]}</small> : null}</span></div>)}</div><div className="milestone-section"><div className="section-title"><h2>Milestones</h2></div><div className="simple-list">{ws.milestones.map(m => <div key={m.id}><strong>{m.title}</strong><span>{project(ws, m.project_id)?.name} · {shortDate(m.due_date)}</span></div>)}</div></div></>; }
function CalendarPage({ ws, contentOnly, mutate, active }: { ws: Workspace; contentOnly?: boolean; mutate: any; active: Profile }) {
  const base = new Date(`${ws.today}T12:00:00`); const first = new Date(base.getFullYear(), base.getMonth(), 1); const offset = (first.getDay() + 6) % 7;
  const days = Array.from({ length: 42 }, (_, i) => new Date(base.getFullYear(), base.getMonth(), i - offset + 1));
  const iso = (d: Date) => { const x = new Date(d); x.setMinutes(x.getMinutes() - x.getTimezoneOffset()); return x.toISOString().slice(0, 10); };
  const drop = (e: React.DragEvent, date: string) => { e.preventDefault(); const id = e.dataTransfer.getData('content'); const c = ws.content.find(x => x.id === id); if (id) mutate(() => updateContent(id, { publish_date: date }, active.id, c?.title), `Publishing date moved to ${shortDate(date)}`); };
  return <><Header eyebrow={contentOnly ? 'CONTENT' : 'WORKSPACE'} title={contentOnly ? 'Content calendar' : 'Unified calendar'} description={contentOnly ? 'Drag content to move its publishing date.' : 'Tasks, follow-ups, project milestones, and content in one operational view.'} /><div className="calendar-toolbar"><button>Today</button><strong>{new Intl.DateTimeFormat('en-IN', { month: 'long', year: 'numeric' }).format(base)}</strong><div className="legend"><span><i className="legend-task" />Task</span><span><i className="legend-content" />Content</span><span><i className="legend-follow" />Follow-up</span></div></div><div className="calendar-grid"><div className="weekdays">{['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(d => <span key={d}>{d}</span>)}</div><div className="calendar-days">{days.map(d => { const date = iso(d), outside = d.getMonth() !== base.getMonth(); const contents = ws.content.filter(c => c.publish_date === date); const tasks = contentOnly ? [] : ws.tasks.filter(t => t.due_date === date); const follows = contentOnly ? [] : ws.tasks.filter(t => t.follow_up_date === date); return <div key={date} className={`${outside ? 'outside' : ''} ${date === ws.today ? 'today' : ''}`} onDragOver={e => e.preventDefault()} onDrop={e => drop(e, date)}><time>{d.getDate()}</time>{contents.slice(0, 3).map(c => <button draggable onDragStart={e => e.dataTransfer.setData('content', c.id)} className="cal-item content" key={c.id}>{platform(ws, c.platform_id)?.name} · {c.title}</button>)}{tasks.slice(0, 2).map(t => <span className="cal-item task" key={t.id}>{t.title}</span>)}{follows.slice(0, 1).map(t => <span className="cal-item follow" key={t.id}>Follow up · {t.title}</span>)}</div>; })}</div></div></>;
}
function ContentPipeline({ ws, setQuick, mutate, active }: { ws: Workspace; setQuick: (x: string) => void; mutate: any; active: Profile }) {
  const stages = ['idea', 'planned', 'research', 'writing', 'design', 'review', 'approved', 'scheduled', 'published'];
  const drop = (e: React.DragEvent, stage: string) => { e.preventDefault(); const id = e.dataTransfer.getData('content'); const c = ws.content.find(x => x.id === id); if (id) mutate(() => updateContent(id, { stage }, active.id, c?.title), `Content moved to ${nice(stage)}`); };
  return <><Header eyebrow="CONTENT" title="Content pipeline" description="Move work from idea to publication with a visible approval state." action={<button className="primary" onClick={() => setQuick('content')}><Plus size={16} /> New content</button>} /><div className="kanban content-board">{stages.map(stage => <div className="kanban-column" key={stage} onDragOver={e => e.preventDefault()} onDrop={e => drop(e, stage)}><div className="column-head"><span><i className={`dot ${stage}`} />{nice(stage)}</span><b>{ws.content.filter(c => c.stage === stage).length}</b></div><div className="column-body">{ws.content.filter(c => c.stage === stage).map(c => <ContentCard key={c.id} item={c} ws={ws} />)}</div></div>)}</div></>;
}
function ContentCard({ item, ws }: { item: ContentItem; ws: Workspace }) { return <button className="task-card content-card" draggable onDragStart={e => e.dataTransfer.setData('content', item.id)}><div className="platform-label">{platform(ws, item.platform_id)?.name}</div><strong>{item.title}</strong><span className="task-project">{item.campaign || 'No campaign'}</span><div className="task-meta"><span>{person(ws, item.owner_id)?.name}</span><time>{shortDate(item.publish_date)}</time></div><Status value={item.approval_status} /></button>; }
function TeamPage({ ws }: { ws: Workspace }) { return <><Header eyebrow="TEAM" title="Who is doing what?" description="Understand the team's current work in under 30 seconds." /><div className="team-grid">{ws.profiles.map(p => { const tasks = ws.tasks.filter(t => t.assignee_id === p.id && ['todo', 'in_progress', 'review', 'blocked'].includes(t.status)); const wl = ws.workload.find(w => w.profile_id === p.id); return <section key={p.id}><div className="person-head"><span className="avatar">{p.name.slice(0, 2).toUpperCase()}</span><div><h3>{p.name}</h3><p>{p.role} · {p.department}</p></div><Status value={wl?.level || 'low'} /></div><div className="working-label">WORKING ON</div>{tasks.length ? tasks.slice(0, 3).map(t => <div className="working-item" key={t.id}><span className={`dot ${t.status}`} /><span><strong>{t.title}</strong><small>{project(ws, t.project_id)?.name}</small></span></div>) : <small>No active assignments</small>}<div className="person-stats"><span><b>{wl?.active || 0}</b> active</span><span><b>{wl?.overdue || 0}</b> overdue</span><span><b>{wl?.blocked || 0}</b> blocked</span></div></section>; })}</div></>; }
function WorkloadPage({ ws }: { ws: Workspace }) { return <><Header eyebrow="TEAM" title="Workload" description="A directional operational indicator—not a measure of productivity." /><div className="notice"><ShieldCheck size={17} /><span>Load combines active, high-priority, due-soon, overdue, and blocked work. Use it to start a conversation, not score people.</span></div><div className="data-table workload-table"><div className="table-head"><span>Person</span><span>Active</span><span>High priority</span><span>Due this week</span><span>Overdue</span><span>Blocked</span><span>Load</span></div>{ws.workload.map(w => <div className="table-row" key={w.profile_id}><span><span className="avatar small">{person(ws, w.profile_id)?.name.slice(0, 2)}</span><strong>{person(ws, w.profile_id)?.name}</strong></span><span>{w.active}</span><span>{w.high}</span><span>{w.due_week}</span><span className={w.overdue ? 'danger-text' : ''}>{w.overdue}</span><span className={w.blocked ? 'danger-text' : ''}>{w.blocked}</span><span><Status value={w.level} /></span></div>)}</div></>; }
function AttentionPage({ ws, setTask }: { ws: Workspace; setTask: (x: string) => void }) { const sections = [['overdue', 'Overdue', 'Past the deadline and not complete.'], ['due_soon', 'Due within 48 hours', 'Work that may need a final push.'], ['blocked', 'Blocked', 'Waiting on a decision, dependency, or access.'], ['stale', 'Stale', 'No update within the configured threshold.'], ['review', 'Waiting for review', 'Ready for a decision or feedback.'], ['follow_up', 'Follow up', 'Your scheduled check-ins are due.']]; return <><Header eyebrow="MANAGEMENT" title="Needs attention" description="What you need to deal with right now—automatically collected." /><div className="attention-stack">{sections.map(([key, title, desc]) => <section key={key}><div className="attention-head"><div><h2>{title}</h2><p>{desc}</p></div><b>{(ws.attention as any)[key].length}</b></div><TaskTable tasks={(ws.attention as any)[key]} ws={ws} setTask={setTask} /></section>)}<section><div className="attention-head"><div><h2>At-risk projects</h2><p>Deadline, progress, blockers, or overdue work indicate risk.</p></div><b>{ws.attention.at_risk.length}</b></div><div className="simple-list">{ws.attention.at_risk.map((p: Project) => <div key={p.id}><strong>{p.name}</strong><span>{p.reasons.join(' · ') || 'Manually marked at risk'}</span></div>)}</div></section></div></>; }
function WeeklyPage({ ws, setTask }: { ws: Workspace; setTask: (x: string) => void }) { const items = [['Completed', 'completed'], ['Overdue', 'overdue'], ['Blocked', 'blocked'], ['Next seven days', 'upcoming']]; return <><Header eyebrow="MANAGEMENT" title="Weekly review" description="A concise operating review of delivery, risk, content, and next week." /><div className="review-summary"><div><small>Completed</small><strong>{ws.weekly.completed.length}</strong></div><div><small>Overdue</small><strong>{ws.weekly.overdue.length}</strong></div><div><small>Blocked</small><strong>{ws.weekly.blocked.length}</strong></div><div><small>Published</small><strong>{ws.weekly.published.length}</strong></div></div><div className="my-work-grid">{items.map(([title, key]) => <section key={key}><div className="section-title"><h2>{title}</h2></div><TaskTable tasks={(ws.weekly as any)[key]} ws={ws} setTask={setTask} /></section>)}<section><div className="section-title"><h2>Project health</h2></div><div className="simple-list">{ws.projects.map(p => <div key={p.id}><strong>{p.name}</strong><span>{p.progress}% · {nice(p.health)}</span></div>)}</div></section><section><div className="section-title"><h2>Upcoming content</h2></div><div className="simple-list">{ws.weekly.contentUpcoming.map((c: ContentItem) => <div key={c.id}><strong>{c.title}</strong><span>{nice(c.stage)} · {shortDate(c.publish_date)}</span></div>)}</div></section></div></>; }
function ActivityPage({ ws }: { ws: Workspace }) { return <><Header eyebrow="MANAGEMENT" title="Activity" description="A compact, attributable history of meaningful workspace changes." /><div className="activity-feed">{ws.activity.map(a => <div key={a.id}><span className="avatar small">{(a.profile_name || 'SS').slice(0, 2)}</span><span><strong>{a.profile_name || 'Shadow Security'}</strong> {a.action}<small>{dateTime(a.created_at)}</small></span></div>)}</div></>; }
function NotesPage({ ws, setQuick, mutate, active }: { ws: Workspace; setQuick: (x: string) => void; mutate: any; active: Profile }) {
  const [newNote, setNewNote] = useState(false); const [title, setTitle] = useState(''); const [body, setBody] = useState('');
  const save = async () => { if (await mutate(() => createNote({ title, body }, active.id), 'Note saved')) { setNewNote(false); setTitle(''); setBody(''); } };
  return <><Header eyebrow="OTHER" title="Notes & meetings" description="Capture decisions and turn action items into assigned work." action={<div className="header-actions"><button onClick={() => setNewNote(true)}><Plus size={16} /> Note</button><button className="primary" onClick={() => setQuick('meeting')}><Plus size={16} /> Meeting note</button></div>} />{newNote ? <section className="note-editor"><input value={title} onChange={e => setTitle(e.target.value)} placeholder="Note title" autoFocus /><textarea value={body} onChange={e => setBody(e.target.value)} placeholder="Write the note…" /><div><button onClick={() => setNewNote(false)}>Cancel</button><button className="primary" onClick={save}>Save note</button></div></section> : null}<div className="notes-layout"><section><div className="section-title"><h2>Workspace notes</h2></div><div className="notes-grid">{ws.notes.map(n => <article key={n.id}><div>{n.pinned ? <span className="pin">PINNED</span> : null}<h3>{n.title}</h3><p>{n.body}</p></div><small>Updated {dateTime(n.updated_at)}</small></article>)}</div></section><section><div className="section-title"><h2>Meeting notes</h2></div><div className="meeting-list">{ws.meetings.map(m => <article key={m.id}><div className="meeting-date">{shortDate(m.meeting_date)}</div><div><h3>{m.title}</h3><p>{m.notes}</p><div className="decision"><strong>Decision</strong>{m.decisions}</div>{m.action_items.map((a, i) => <div className="action-item" key={i}><span className={a.done ? 'done' : ''}>{a.done ? '✓' : '○'} {a.text}</span>{!a.done ? <button onClick={() => setQuick(`convert:${m.id}:${a.text}`)}>Convert to task</button> : null}</div>)}</div></article>)}</div></section></div></>;
}
function SettingsPage({ ws, mutate, active }: { ws: Workspace; mutate: any; active: Profile }) {
  const [member, setMember] = useState({ name: '', role: '', department: '', email: '' });
  const [platformName, setPlatformName] = useState('');
  const addMember = async () => { if (await mutate(() => addProfile(member, active.id), 'Team member added—ask them to sign up with this email')) setMember({ name: '', role: '', department: '', email: '' }); };
  return <><Header eyebrow="OTHER" title="Settings" description="Workspace preferences, team, platforms, and data." /><div className="settings-sections"><section><h2>Team</h2><p>Add the person's email here first. They can then create their own password by signing up with that exact email.</p><div className="form-grid"><Field label="Name"><input value={member.name} onChange={e => setMember({ ...member, name: e.target.value })} /></Field><Field label="Role"><input value={member.role} onChange={e => setMember({ ...member, role: e.target.value })} /></Field><Field label="Department"><input value={member.department} onChange={e => setMember({ ...member, department: e.target.value })} /></Field><Field label="Work email"><input type="email" required value={member.email} onChange={e => setMember({ ...member, email: e.target.value })} /></Field></div><button className="primary" onClick={addMember} disabled={!member.name || !member.role || !member.email}><Plus size={16} /> Add member</button></section><section><h2>Content platforms</h2><p>Current: {ws.platforms.map(p => p.name).join(', ')}</p><div className="inline-form"><input value={platformName} onChange={e => setPlatformName(e.target.value)} placeholder="New platform" /><button onClick={async () => { if (await mutate(() => addPlatform(platformName), 'Platform added')) setPlatformName(''); }}>Add</button></div></section><section><h2>Backup workspace</h2><p>Downloads a dated JSON file with everything in this workspace right now.</p><button className="primary" onClick={() => downloadBackup(ws)}>Download backup</button></section><section><h2>Your account</h2><p>Signed in as {active.email} · {active.access_role === 'admin' ? 'Admin' : 'Member'}</p></section></div></>;
}

function TaskDrawer({ ws, taskId, close, mutate, actorId }: { ws: Workspace; taskId: string; close: () => void; mutate: any; actorId: string }) {
  const task = ws.tasks.find(t => t.id === taskId); const [comment, setComment] = useState(''); const [check, setCheck] = useState('');
  if (!task) return null;
  const checks = ws.checklist.filter(c => c.task_id === task.id), comments = ws.comments.filter(c => c.task_id === task.id);
  const patch = (value: Partial<Task>, message = 'Task updated') => mutate(() => updateTask(task.id, value, actorId, task), message);
  return <><div className="scrim drawer-scrim" onClick={close} /><aside className="drawer"><div className="drawer-head"><div><Status value={task.status} /><span className="muted-id">{task.id}</span></div><button className="icon" onClick={close}><X size={19} /></button></div><div className="drawer-scroll"><input className="task-title-input" defaultValue={task.title} onBlur={e => e.target.value !== task.title && patch({ title: e.target.value })} /><textarea className="description" defaultValue={task.description} onBlur={e => e.target.value !== task.description && patch({ description: e.target.value })} placeholder="Add a clear description…" /><div className="properties"><Field label="Status"><select value={task.status} onChange={e => patch({ status: e.target.value as Status }, `Moved to ${nice(e.target.value)}`)}>{['backlog', 'todo', 'in_progress', 'review', 'blocked', 'done'].map(x => <option key={x} value={x}>{nice(x)}</option>)}</select></Field><Field label="Assignee"><select value={task.assignee_id || ''} onChange={e => patch({ assignee_id: e.target.value || null })}><option value="">Unassigned</option>{ws.profiles.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><Field label="Project"><select value={task.project_id || ''} onChange={e => patch({ project_id: e.target.value || null })}><option value="">No project</option>{ws.projects.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><Field label="Priority"><select value={task.priority} onChange={e => patch({ priority: e.target.value as Task['priority'] })}>{['low', 'medium', 'high', 'urgent'].map(x => <option key={x}>{x}</option>)}</select></Field><Field label="Due date"><input type="date" value={task.due_date || ''} onChange={e => patch({ due_date: e.target.value || null })} /></Field><Field label="Start date"><input type="date" value={task.start_date || ''} onChange={e => patch({ start_date: e.target.value || null })} /></Field><Field label="Follow-up"><input type="date" value={task.follow_up_date || ''} onChange={e => patch({ follow_up_date: e.target.value || null })} /></Field></div><section className="drawer-section"><div className="section-title"><h2>Checklist</h2><span>{checks.filter(c => c.completed).length}/{checks.length}</span></div>{checks.map(c => <div className="check-row" key={c.id}><input type="checkbox" checked={c.completed} onChange={() => mutate(() => setChecklistItem(c.id, !c.completed), 'Checklist updated')} /><span className={c.completed ? 'done' : ''}>{c.text}</span><button onClick={() => mutate(() => deleteChecklistItem(c.id), 'Checklist item removed')}><X size={14} /></button></div>)}<div className="inline-form"><input value={check} onChange={e => setCheck(e.target.value)} placeholder="Add checklist item" /><button onClick={async () => { if (await mutate(() => addChecklistItem(task.id, check), 'Checklist item added')) setCheck(''); }}>Add</button></div></section><section className="drawer-section"><div className="section-title"><h2>Blocker</h2></div>{task.blocked_reason ? <div className="blocker"><AlertTriangle size={17} /><span>{task.blocked_reason}</span><button onClick={() => patch({ blocked_reason: null, status: 'in_progress' }, 'Blocker cleared')}>Clear</button></div> : <button className="secondary" onClick={() => { const reason = prompt("What's blocking this?"); if (reason) patch({ blocked_reason: reason, status: 'blocked' }, 'Task marked blocked'); }}><Blocks size={16} /> Mark as blocked</button>}</section><section className="drawer-section"><div className="section-title"><h2>Comments</h2><span>{comments.length}</span></div>{comments.map(c => <div className="comment" key={c.id}><span className="avatar small">{person(ws, c.profile_id)?.name.slice(0, 2)}</span><div><strong>{person(ws, c.profile_id)?.name}</strong><small>{dateTime(c.created_at)}</small><p>{c.body}</p></div></div>)}<div className="comment-box"><textarea value={comment} onChange={e => setComment(e.target.value)} placeholder="Add a useful update…" /><button className="primary" onClick={async () => { if (await mutate(() => addComment(task.id, comment, actorId), 'Comment added')) setComment(''); }} disabled={!comment.trim()}>Comment</button></div></section></div><div className="drawer-foot"><button className="danger-button" onClick={() => confirm('Archive this task?') && mutate(() => archiveTask(task.id, task.title, actorId), 'Task archived').then(close)}><Archive size={15} /> Archive task</button></div></aside></>;
}
function QuickAdd({ type, ws, actor, close, mutate }: { type: string; ws: Workspace; actor: Profile; close: () => void; mutate: any }) {
  const convert = type.startsWith('convert:'); const parts = type.split(':'); const kind = convert ? 'convert' : type;
  const [form, setForm] = useState<any>({ title: convert ? parts.slice(2).join(':') : '', assignee_id: '', project_id: '', priority: 'medium', due_date: '', status: 'todo', owner_id: actor.id, platform_id: ws.platforms[0]?.id, stage: 'idea', meeting_date: ws.today, notes: '', decisions: '', action_items: '', description: '', deadline: '' });
  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (kind === 'task') await mutate(() => createTask(form, actor.id), 'Task created');
    else if (kind === 'project') await mutate(() => createProject(form, actor.id), 'Project created');
    else if (kind === 'content') await mutate(() => createContent(form, actor.id), 'Content created');
    else if (kind === 'meeting') await mutate(() => createMeeting(form, actor.id), 'Meeting note created');
    else if (kind === 'convert') await mutate(() => convertActionToTask(parts[1], form, actor.id), 'Task created');
    close();
  };
  return <><div className="scrim modal-scrim" onClick={close} /><div className="modal"><div className="modal-head"><div><div className="eyebrow">QUICK ADD</div><h2>{kind === 'convert' ? 'Convert to task' : `New ${kind}`}</h2></div><button className="icon" onClick={close}><X size={19} /></button></div><form onSubmit={submit}><Field label={kind === 'meeting' ? 'Meeting title' : kind === 'content' ? 'Content title' : kind === 'project' ? 'Project name' : 'Task name'}><input autoFocus required value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} /></Field>{kind === 'task' || kind === 'convert' ? <div className="form-grid"><Field label="Assignee"><select value={form.assignee_id} onChange={e => setForm({ ...form, assignee_id: e.target.value })}><option value="">Unassigned</option>{ws.profiles.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><Field label="Project"><select value={form.project_id} onChange={e => setForm({ ...form, project_id: e.target.value })}><option value="">No project</option>{ws.projects.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><Field label="Priority"><select value={form.priority} onChange={e => setForm({ ...form, priority: e.target.value })}>{['low', 'medium', 'high', 'urgent'].map(x => <option key={x}>{nice(x)}</option>)}</select></Field><Field label="Due date"><input type="date" value={form.due_date} onChange={e => setForm({ ...form, due_date: e.target.value })} /></Field></div> : null}{kind === 'project' ? <><Field label="Description"><textarea value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} /></Field><div className="form-grid"><Field label="Owner"><select value={form.owner_id} onChange={e => setForm({ ...form, owner_id: e.target.value })}>{ws.profiles.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><Field label="Deadline"><input type="date" value={form.deadline} onChange={e => setForm({ ...form, deadline: e.target.value })} /></Field></div></> : null}{kind === 'content' ? <div className="form-grid"><Field label="Platform"><select value={form.platform_id} onChange={e => setForm({ ...form, platform_id: e.target.value })}>{ws.platforms.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><Field label="Owner"><select value={form.owner_id} onChange={e => setForm({ ...form, owner_id: e.target.value })}>{ws.profiles.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><Field label="Publish date"><input type="date" value={form.publish_date || ''} onChange={e => setForm({ ...form, publish_date: e.target.value })} /></Field><Field label="Stage"><select value={form.stage} onChange={e => setForm({ ...form, stage: e.target.value })}>{['idea', 'planned', 'research', 'writing', 'design', 'review', 'approved', 'scheduled', 'published'].map(x => <option key={x}>{x}</option>)}</select></Field></div> : null}{kind === 'meeting' ? <><Field label="Date"><input type="date" value={form.meeting_date} onChange={e => setForm({ ...form, meeting_date: e.target.value })} /></Field><Field label="Notes"><textarea value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} /></Field><Field label="Decisions"><textarea value={form.decisions} onChange={e => setForm({ ...form, decisions: e.target.value })} /></Field><Field label="Action items (one per line)"><textarea value={form.action_items} onChange={e => setForm({ ...form, action_items: e.target.value })} /></Field></> : null}<div className="modal-actions"><button type="button" onClick={close}>Cancel</button><button className="primary" type="submit">Create {kind === 'convert' ? 'task' : kind}</button></div></form></div></>;
}
function SearchPalette({ ws, close, go, setTask }: { ws: Workspace; close: () => void; go: (x: string) => void; setTask: (x: string) => void }) {
  const [q, setQ] = useState(''); const input = useRef<HTMLInputElement>(null); useEffect(() => input.current?.focus(), []);
  const results = useMemo(() => { if (!q.trim()) return []; const s = q.toLowerCase(); return [...ws.tasks.filter(x => x.title.toLowerCase().includes(s)).map(x => ({ id: x.id, label: x.title, type: 'task' })), ...ws.projects.filter(x => x.name.toLowerCase().includes(s)).map(x => ({ id: x.id, label: x.name, type: 'project' })), ...ws.profiles.filter(x => `${x.name} ${x.role}`.toLowerCase().includes(s)).map(x => ({ id: x.id, label: x.name, type: 'person' })), ...ws.content.filter(x => x.title.toLowerCase().includes(s)).map(x => ({ id: x.id, label: x.title, type: 'content' })), ...ws.notes.filter(x => `${x.title} ${x.body}`.toLowerCase().includes(s)).map(x => ({ id: x.id, label: x.title, type: 'note' }))].slice(0, 18); }, [q, ws]);
  const open = (r: any) => { if (r.type === 'task') setTask(r.id); else go(r.type === 'project' ? 'projects' : r.type === 'person' ? 'team' : r.type === 'content' ? 'content-pipeline' : 'notes'); close(); };
  return <><div className="scrim modal-scrim" onClick={close} /><div className="search-palette"><div className="search-input"><CircleUserRound size={19} /><input ref={input} value={q} onChange={e => setQ(e.target.value)} placeholder="Search tasks, people, projects, content, notes…" /><kbd>ESC</kbd></div><div className="search-results">{q && !results.length ? <Empty compact title="No results" text="Try another name or keyword." /> : results.map(r => <button key={`${r.type}-${r.id}`} onClick={() => open(r)}><span className="result-icon">{r.type === 'task' ? <ListChecks /> : r.type === 'project' ? <FolderKanban /> : r.type === 'person' ? <CircleUserRound /> : r.type === 'content' ? <CalendarDays /> : <FileText />}</span><span><strong>{r.label}</strong><small>{nice(r.type)}</small></span></button>)}</div></div></>;
}
function Field({ label, children }: { label: string; children: React.ReactNode }) { return <label className="field"><span>{label}</span>{children}</label>; }
function Status({ value }: { value: string }) { return <span className={`status ${value}`}>{nice(value)}</span>; }
function Priority({ value }: { value: string }) { return <span className={`priority ${value}`}><i />{nice(value)}</span>; }
function Empty({ title, text, compact }: { title: string; text?: string; compact?: boolean }) { return <div className={`empty ${compact ? 'compact' : ''}`}><Blocks size={compact ? 18 : 24} /><strong>{title}</strong>{text ? <span>{text}</span> : null}</div>; }
